// Leaderboard controls use one delegated handler so they remain reliable across redraws and touch browsers.
document.addEventListener('click', event => {
  const tab = event.target.closest('.leaderboard-tab');
  if (tab) {
    event.preventDefault();
    leaderboardView = tab.dataset.view;
    renderLeaderboardDashboard();
    return;
  }
  const direction = event.target.closest('#leaderboard-prev, #leaderboard-next');
  if (!direction || direction.disabled) return;
  event.preventDefault();
  const older = direction.id === 'leaderboard-prev';
  if (leaderboardView === 'month') recentStart += older ? 1 : -1;
  else leaderboardYearIndex += older ? 1 : -1;
  renderLeaderboardDashboard();
});
function renderHeroPlayerResults(query) {
  const labels = language === 'en' ? { displayName:'Display Name', englishName:'ローマ字表記 / Romanized name', id:'Player ID', category:'Category', gender:'Gender', handStyle:'Hand / Style', grip:'Grip', games:'Completed Games', record:'W / L', rate:'Win %', empty:'No players found' } : { displayName:'表示名', englishName:'ローマ字表記 / Romanized name', id:'選手ID', category:'カテゴリ', gender:'性別', handStyle:'利き手 / 戦型', grip:'グリップ', games:'完了試合数', record:'勝 / 負', rate:'勝率', empty:'該当する選手がいません' };
  const stats = playerStats(data.matches), results = data.players.filter(player => `${player.playerId} ${player.displayName} ${player.englishName || ''}`.toLowerCase().includes(query)).slice(0,8);
  document.querySelector('#hero-player-results').innerHTML = results.map(player => {
    const record = stats.get(player.playerId) || { wins:0, losses:0 }, games = record.wins + record.losses, rate = games ? Math.round(record.wins / games * 100) : 0;
    const details = [[labels.category,lookupValue('schoolLevel',player.schoolLevel)],[labels.gender,player.gender],[labels.handStyle,[player.playingHand,player.playingStyle].filter(Boolean).join(' / ')],[labels.grip,player.grip]].filter(([,value]) => value);
    return `<a class="hero-player-card" href="player.html?id=${encodeURIComponent(player.playerId)}"><figure class="hero-player-portrait"><img src="img/${encodeURIComponent(player.playerId)}.jpg" alt="${escapeHtml(player.displayName || player.englishName || player.playerId)}"></figure><div class="hero-player-card-main"><div class="hero-player-names"><span><small>${labels.displayName}</small><b>${escapeHtml(player.displayName || '-')}</b></span><span><small>${labels.englishName}</small><b>${escapeHtml(player.englishName?.toUpperCase() || '-')}</b></span></div><div class="hero-player-profile"><span><b>${labels.id}</b>${escapeHtml(player.playerId || '-')}</span>${details.map(([label,value]) => `<span><b>${label}</b>${escapeHtml(value)}</span>`).join('')}</div><div class="hero-player-record"><span><b>${labels.games}</b>${games}</span><span><b>${labels.record}</b>${record.wins} / ${record.losses}</span><span><b>${labels.rate}</b>${rate}%</span></div></div></a>`;
  }).join('') || `<p class="hero-player-empty">${labels.empty}</p>`;
}
const howToRead = {
  yearly: { en: { title:'How to Read the Yearly Leaderboard', intro:'Rankings compare players within the same category for the selected year.', points:['Check eligibility first: a player needs one completed match for every recorded match day that year.','Win rate is most useful alongside the W/L total and number of games. A strong rate from fewer matches is a smaller sample.','Use the opponent-category record to understand where results were earned. Different opponent pools create different challenges.','Treat the table as a review tool, not a judgement of player quality. Look for training priorities, not labels.'] }, ja: { title:'年間リーダーボードの見方', intro:'選択した年の同じカテゴリ内で順位を比較しています。', points:['まず対象条件を確認します。その年のすべての試合日に、完了試合を1試合以上行う必要があります。','勝率は勝敗数と試合数と合わせて確認します。試合数が少ない高勝率は、判断材料がまだ少ない場合があります。','対戦相手カテゴリ別の勝敗を見ると、どの相手層との結果かを理解できます。対戦相手の構成によって難易度は変わります。','順位は選手の良し悪しを決めるものではありません。次の練習課題を見つけるために活用してください。'] } },
  monthly: { en: { title:'How to Read the Monthly Leaderboard', intro:'This view is a short-term training snapshot for each displayed month.', points:['Eligibility is a total of at least 2 × the number of match days in that month.','Compare a month with the previous month to spot changes in consistency, participation, and win rate.','Read W/L and opponent-category records together. A lower rate against a stronger or unfamiliar group can still reveal useful progress.','Use the result to set one practical next focus, such as serve receive, third-ball attack, or closing close games.'] }, ja: { title:'月間リーダーボードの見方', intro:'表示月ごとの短期的な練習状況を確認するための一覧です。', points:['対象条件は、その月の試合日数 × 2試合以上の合計完了試合数です。','前月と比べて、安定感、参加状況、勝率の変化を確認してください。','勝敗と対戦相手カテゴリ別の記録を合わせて見ます。強い相手や慣れない相手が多い月は、勝率が低くても有意義な成長が見える場合があります。','サーブレシーブ、3球目攻撃、接戦の締め方など、次の練習テーマを1つ決めるために使ってください。'] } },
  volume: { en: { title:'How to Read Match-Day Volume', intro:'The chart shows how much competitive practice happened on each training day.', points:['Blue bars show participating players. The gold line shows completed and recorded matches.','More matches create more repetition and feedback, but volume alone does not measure quality.','Look for days with many matches and revisit those session results to identify recurring score patterns or difficult opponents.','Combine volume with win rate, score lines, and your own match notes before changing training priorities.'] }, ja: { title:'試合日別試合数の見方', intro:'各練習日に、どれだけ実戦形式の練習が行われたかを示すグラフです。', points:['青い棒は参加選手数、金色の線は記録された完了試合数です。','試合数が多いほど反復と振り返りの機会は増えますが、量だけで練習の質は判断できません。','試合数が多い日の結果を見直し、繰り返し出るスコア傾向や苦手な相手を確認してください。','練習テーマを変える前に、試合数、勝率、スコア、自分のメモを合わせて判断してください。'] } },
  sessions: { en: { title:'How to Read Session Replay', intro:'Choose a training date to review the individual matches played that day.', points:['Read the score, result, and opponent together. A 3-2 result contains different information from a 3-0 result.','Close losses can point to decision-making under pressure, serve/receive quality, or the final-ball pattern.','Incomplete matches are shown for the record but are excluded from performance statistics and rankings.','After reviewing a session, write down one successful pattern and one situation to practise next time.'] }, ja: { title:'練習日リプレイの見方', intro:'練習日を選ぶと、その日に行われた個別の試合を振り返れます。', points:['スコア、結果、対戦相手を一緒に確認してください。3-2の試合と3-0の試合では、得られる情報が異なります。','接戦での敗戦は、プレッシャー下の判断、サーブレシーブ、終盤の得点パターンなどの課題を示すことがあります。','未完了試合は記録として表示されますが、成績やランキングの集計には含まれません。','振り返った後、うまくできたパターンを1つ、次回練習する場面を1つ書き出してください。'] } },
  players: { en: { title:'How to Use Player Profiles', intro:'Select a player to see their training record, trends, opponent matchups, and available playing information.', points:['Use the match timeline to see consistency over several training days, rather than reacting to one result.','Opponent insights help identify repeated matchups and whether adjustments are needed in tactics or preparation.','Equipment and playing-style details are reference information for understanding a player, not a prescription for changing gear.','Discuss patterns with the player and coach, then turn the review into a small, measurable practice goal.'] }, ja: { title:'選手プロフィールの活用方法', intro:'選手を選ぶと、練習記録、成績推移、対戦相手との記録、登録済みのプレー情報を確認できます。', points:['1試合の結果だけで判断せず、複数の練習日にわたる推移から安定感を確認してください。','対戦相手分析では、繰り返し対戦する相手や、戦術・準備の見直しが必要な組み合わせを確認できます。','用具やプレースタイルの情報は選手を理解するための参考です。すぐに用具変更を勧めるためのものではありません。','選手とコーチで傾向を話し合い、小さく測定可能な練習目標に変えてください。'] } }
};
howToRead.h2h = { en: { title:'How to Read Head to Head', intro:'This view compares only the two selected players across their recorded meetings.', points:['The bars show the result of each match in time order: win, loss, or draw.','Read the score list with the timeline. Repeated close losses and repeated one-sided losses suggest different training questions.','Use the history to identify one matchup-specific focus, such as serve placement, receive choice, first attack, or rally pattern.','A Head-to-Head record is a tactical review tool, not a fixed measure of either player’s level.'] }, ja: { title:'直接対決の見方', intro:'選択した2選手の記録済み対戦だけを比較する画面です。', points:['棒は時系列の各試合結果を示し、勝ち・負け・引分を確認できます。','スコア一覧とタイムラインを合わせて見ます。接戦の敗戦が続く場合と一方的な敗戦が続く場合では、考える練習課題が異なります。','サーブのコース、レシーブの選択、先手の取り方、ラリーのパターンなど、対戦相手別の課題を1つ決めてください。','直接対決の記録は戦術を振り返るためのものであり、選手の実力を固定的に決めるものではありません。'] } };
 document.addEventListener('click', event => { const button = event.target.closest('.how-to-read'); if (!button) return; const content = howToRead[button.dataset.help]?.[language]; if (!content) return; const parentDialog = button.closest('dialog'); if (parentDialog && parentDialog.id !== 'how-to-read-dialog') { let panel = parentDialog.querySelector('.inline-how-to-read'), exists = Boolean(panel); if (!panel) { panel = document.createElement('section'); panel.className = 'inline-how-to-read'; parentDialog.querySelector('[id$="-content"]').append(panel); } panel.innerHTML = `<b>${content.title}</b><p>${content.intro}</p><ul>${content.points.map(point => `<li>${point}</li>`).join('')}</ul>`; panel.hidden = exists ? !panel.hidden : false; return; } document.querySelector('#how-to-read-content').innerHTML = `<p class="eyebrow">${language === 'en' ? 'HOW TO READ' : '見方'}</p><h2>${content.title}</h2><p>${content.intro}</p><ul>${content.points.map(point => `<li>${point}</li>`).join('')}</ul>`; document.querySelector('#how-to-read-dialog').showModal(); });
document.addEventListener('click', event => { const card = event.target.closest('.match-card'); if (card?.dataset.matchId) { const match = data.matches.find(item => item.matchId === card.dataset.matchId); if (match) location.href = `player.html?id=${match.player1Id}&opponent=${match.player2Id}`; } if (event.target.closest('.modal-close')) document.querySelectorAll('dialog[open]').forEach(dialog => dialog.close()); const categoryButton = event.target.closest('.category-ranking-open'); if (categoryButton && !categoryButton.dataset.month) { const category = categoryButton.dataset.category, entries = categoryLeaderboardEntries.get(category) || [], title = language === 'en' ? `${categoryLeaderboardYear} ${category} Rankings` : `${categoryLeaderboardYear}年 ${category} 順位`, winLabel = language === 'en' ? 'W' : '勝', lossLabel = language === 'en' ? 'L' : '負'; document.querySelector('#category-leaderboard-content').innerHTML = `<p class="eyebrow">${language === 'en' ? 'YEARLY CATEGORY RANKING' : '年間カテゴリ順位'}</p><button class="how-to-read h2h-help" data-help="yearly" aria-label="${language === 'en' ? 'How to read category rankings' : 'カテゴリ順位の見方'}">?</button><h2>${title}</h2><ol>${entries.map((entry,index) => { const games = entry.stats.wins + entry.stats.losses, rate = Math.round(entry.stats.wins / games * 100), categories = opponentCategoryBreakdown(categoryLeaderboardMatches, entry.player.playerId).replace(/\n/g, ' · '); return `<li><i>${rankIcon(index)}</i><a class="player-link" href="player.html?id=${entry.player.playerId}">${nameFor(entry.player)}</a><b>${rate}%</b><span>${winLabel}${entry.stats.wins} · ${lossLabel}${entry.stats.losses} · ${language === 'en' ? `${games}G` : `${games}試合`}</span><span class="leader-category-records">${categories}</span></li>`; }).join('')}</ol>`; document.querySelector('#category-leaderboard').showModal(); } });
document.addEventListener('click', event => { const button = event.target.closest('.category-ranking-open[data-month]'); if (!button) return; const category = button.dataset.category, month = button.dataset.month, entries = monthlyCategoryEntries.get(`${month}|${category}`) || [], matches = monthlyCategoryMatches.get(`${month}|${category}`) || [], title = language === 'en' ? `${month} ${category} Rankings` : `${month} ${category} 順位`, winLabel = language === 'en' ? 'W' : '勝', lossLabel = language === 'en' ? 'L' : '負'; document.querySelector('#category-leaderboard-content').innerHTML = `<p class="eyebrow">${language === 'en' ? 'MONTHLY CATEGORY RANKING' : '月間カテゴリ順位'}</p><button class="how-to-read h2h-help" data-help="monthly" aria-label="${language === 'en' ? 'How to read category rankings' : 'カテゴリ順位の見方'}">?</button><h2>${title}</h2><ol>${entries.map((entry,index) => { const games = entry.stats.wins + entry.stats.losses, rate = Math.round(entry.stats.wins / games * 100), categories = opponentCategoryBreakdown(matches, entry.player.playerId).replace(/\n/g, ' · '); return `<li><i>${rankIcon(index)}</i><a class="player-link" href="player.html?id=${entry.player.playerId}">${nameFor(entry.player)}</a><b>${rate}%</b><span>${winLabel}${entry.stats.wins} · ${lossLabel}${entry.stats.losses} · ${language === 'en' ? `${games}G` : `${games}試合`}</span><span class="leader-category-records">${categories}</span></li>`; }).join('')}</ol>`; document.querySelector('#category-leaderboard').showModal(); });
document.addEventListener('click', event => { const button = event.target.closest('.category-ranking-open'); if (!button) return; const matches = button.dataset.month ? monthlyCategoryMatches.get(`${button.dataset.month}|${button.dataset.category}`) || [] : categoryLeaderboardMatches; document.querySelectorAll('#category-leaderboard-content li').forEach(item => { const playerId = item.querySelector('a')?.href.match(/[?&]id=([^&]+)/)?.[1]; item.querySelector('.leader-category-records')?.remove(); if (playerId) item.insertAdjacentHTML('beforeend', opponentCategoryDistribution(matches, playerId)); }); });
const addYearlyAvatars = () => { const dialog = document.querySelector('#category-leaderboard-content'), isYearlyDialog = dialog.querySelector('.eyebrow')?.textContent.includes(language === 'en' ? 'YEARLY' : '年間'); const links = [...document.querySelectorAll('#leaderboard-content .player-link'), ...(isYearlyDialog ? dialog.querySelectorAll('.player-link') : [])]; links.filter(link => { if (link.classList.contains('yearly-avatar-missing')) return false; const parent = link.closest('b') || link.parentElement, hasAvatar = link.previousElementSibling?.matches('.yearly-avatar, .monthly-avatar') || parent?.previousElementSibling?.matches('.yearly-avatar, .monthly-avatar'); return !hasAvatar; }).forEach(link => { const playerId = new URL(link.href).searchParams.get('id'); if (!playerId) return; const portrait = document.createElement('figure'), image = document.createElement('img'); portrait.className = 'yearly-avatar'; image.src = `img/${encodeURIComponent(playerId)}.jpg`; image.alt = ''; image.onerror = () => { link.classList.add('yearly-avatar-missing'); portrait.remove(); }; portrait.append(image); link.before(portrait); }); };
new MutationObserver(addYearlyAvatars).observe(document.body, { childList:true, subtree:true });
 document.addEventListener('click', event => { const row = event.target.closest('#player-setup-distribution .setup-row'); if (!row) return; const section = row.closest('section'), fields = ['playingStyle','grip','forehandRubberType','backhandRubberType'], field = fields[[...section.parentElement.children].indexOf(section)], value = row.querySelector('span')?.getAttribute('title'), members = data.players.filter(player => lookupValue(field, player[field]) === value); if (members.length) openActivePlayerList(value, members); });
